  "truncated": false,
  "entry_count": 3
}

ACTION CONTRACT:
{
  "actions": {
    "write_file": {
      "description": "Atomically write UTF-8 text inside the workspace.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "content": "text",
        "overwrite": {
          "type": "boolean",
          "const": true,
          "description": "must be true to preserve idempotent retry"
        },
        "create_parents": "boolean"
      },
      "required_arguments": [
        "path",
        "content"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "write_json": {
      "description": "Atomically serialize a JSON value inside the workspace.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "value": "any JSON value"
      },
      "required_arguments": [
        "path",
        "value"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "replace_text": {
      "description": "Replace an exact text occurrence in an existing UTF-8 file.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "old": "exact text",
        "new": "replacement",
        "count": "positive integer"
      },
      "required_arguments": [
        "path",
        "old",
        "new"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "remove_line": {
      "description": "Remove a complete UTF-8 text line from an existing file.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "text": "line text without newline",
        "all": "boolean"
      },
      "required_arguments": [
        "path",
        "text"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "append_file": {
      "description": "Append UTF-8 text; this action is non-idempotent.",
      "read_only": false,
      "side_effect": true,
      "idempotent": false,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "content": "text"
      },
      "required_arguments": [
        "path",
        "content"
      ],
      "required_postconditions": [
        "file_contains"
      ]
    },
    "delete_file": {
      "description": "Delete one explicitly scoped path.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "missing_ok": "boolean",
        "recursive": "boolean"
      },
      "required_arguments": [
        "path"
      ],
      "required_postconditions": [
        "file_absent"
      ]
    },
    "make_directory": {
      "description": "Create a directory inside the workspace.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "parents": "boolean"
      },
      "required_arguments": [
        "path"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "copy_file": {
      "description": "Copy one scoped file to another scoped path.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "source": "relative path",
        "destination": "relative path"
      },
      "required_arguments": [
        "source",
        "destination"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "list_directory": {
      "description": "List bounded file and directory metadata inside the workspace without reading file contents.",
      "read_only": true,
      "side_effect": false,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative directory; defaults to workspace root",
        "recursive": "boolean",
        "max_entries": "positive integer up to 1024"
      },
      "required_arguments": [],
      "required_postconditions": []
    },
    "read_file": {
      "description": "Read a UTF-8 file without modifying it.",
      "read_only": true,
      "side_effect": false,
      "idempotent": true,
      "default_timeout": 30.0,
